16	type handler struct{ store *Store }
17	
18	func NewHandler(store *Store) http.Handler {
19		h := &handler{store: store}
20		mux := http.NewServeMux()
21		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
22			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
23		})
24		mux.HandleFunc("POST /v1/devices", h.register)
25		mux.HandleFunc("POST /v1/devices/{id}/telemetry", h.telemetry)
26		mux.HandleFunc("POST /v1/devices/{id}/replay", h.replay)
27		mux.HandleFunc("GET /v1/devices/{id}/history", h.history)
28		mux.HandleFunc("GET /v1/devices/{id}/history/retention", h.getRetention)
29		mux.HandleFunc("PUT /v1/devices/{id}/history/retention", h.setRetention)
30		mux.HandleFunc("GET /v1/fleet", h.snapshot)
31		mux.HandleFunc("POST /v1/devices/{id}/rules", h.createRule)
32		mux.HandleFunc("GET /v1/devices/{id}/rules", h.listRules)
33		mux.HandleFunc("GET /v1/devices/{id}/rules/{ruleId}", h.getRule)
34		mux.HandleFunc("PUT /v1/devices/{id}/rules/{ruleId}", h.updateRule)
35		mux.HandleFunc("POST /v1/devices/{id}/alerts/{alertId}/acknowledge", h.ackAlert)
36		mux.HandleFunc("GET /v1/devices/{id}/alerts", h.listAlerts)
37		mux.HandleFunc("POST /v1/devices/{id}/configs", h.publishConfig)
38		mux.HandleFunc("GET /v1/devices/{id}/configs", h.listConfigs)
39		mux.HandleFunc("GET /v1/devices/{id}/configs/pending", h.pendingConfig)
40		mux.HandleFunc("GET /v1/devices/{id}/configs/status", h.configStatus)
41		mux.HandleFunc("POST /v1/devices/{id}/configs/receipts", h.receiveConfigReceipt)
42		mux.HandleFunc("GET /v1/devices/{id}/configs/receipts", h.listConfigReceipts)
43		mux.HandleFunc("POST /v1/devices/{id}/tasks", h.createTask)
44		mux.HandleFunc("GET /v1/devices/{id}/tasks", h.listTasks)
45		mux.HandleFunc("POST /v1/devices/{id}/tasks/claim", h.claimTask)
46		mux.HandleFunc("GET /v1/devices/{id}/tasks/{taskId}", h.getTask)
47		mux.HandleFunc("POST /v1/devices/{id}/tasks/{taskId}/reports", h.reportTask)
48		mux.HandleFunc("POST /v1/devices/{id}/tasks/{taskId}/cancel", h.cancelTask)
49		mux.HandleFunc("GET /v1/devices/{id}/tasks/{taskId}/audit", h.listTaskAudit)
50		return mux
51	}
