78	func (h *handler) telemetry(w http.ResponseWriter, r *http.Request) {
79		values := map[string]float64{}
80		if err := decodeJSON(r, &values); err != nil || len(values) == 0 {
81			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values are required"})
82			return
83		}
84		if !finiteValues(values) {
85			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values must be finite"})
86			return
87		}
88		device, err := h.store.RecordTelemetry(r.PathValue("id"), values)
89		if errors.Is(err, ErrDeviceNotFound) {
90			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
91			return
92		}
93		if errors.Is(err, ErrStorageUnavailable) {
94			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
95			return
96		}
97		if err != nil {
98			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
99			return
100		}
101		writeJSON(w, http.StatusAccepted, device)
102	}
