184	func (h *handler) history(w http.ResponseWriter, r *http.Request) {
185		id := r.PathValue("id")
186		query := r.URL.Query()
187	
188		filter := HistoryFilter{}
189		if raw := strings.TrimSpace(query.Get("from")); raw != "" {
190			from, err := time.Parse(time.RFC3339, raw)
191			if err != nil {
192				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must be RFC3339 formatted"})
193				return
194			}
195			filter.From = from.UTC()
196		}
197		if raw := strings.TrimSpace(query.Get("to")); raw != "" {
198			to, err := time.Parse(time.RFC3339, raw)
199			if err != nil {
200				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "to must be RFC3339 formatted"})
201				return
202			}
203			filter.To = to.UTC()
204		}
205		if !filter.From.IsZero() && !filter.To.IsZero() && filter.From.After(filter.To) {
206			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must not be after to"})
207			return
208		}
209	
210		limit := 20
211		if raw := strings.TrimSpace(query.Get("limit")); raw != "" {
212			value, err := strconv.Atoi(raw)
213			if err != nil || value < 1 || value > 100 {
214				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "limit must be between 1 and 100"})
215				return
216			}
217			limit = value
218		}
219	
220		var startSeq, highWater int64
221		rawCursor := strings.TrimSpace(query.Get("cursor"))
222		if rawCursor != "" {
223			// An unknown device is always 404, even with a malformed or foreign
224			// cursor; cursor problems on a registered device are 400.
225			if !h.store.Exists(id) {
226				writeJSON(w, http.StatusNotFound, map[string]string{"error": ErrDeviceNotFound.Error()})
227				return
228			}
229			cursor, err := decodeCursor(rawCursor)
230			if err != nil || cursor.DeviceID != id ||
231				!cursor.From.Equal(filter.From) || !cursor.To.Equal(filter.To) ||
232				!bytes.Equal(cursor.IID, h.store.instanceID()) {
233				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid cursor"})
234				return
235			}
236			startSeq, highWater = cursor.StartSeq, cursor.HighWater
237		}
238	
239		events, appliedBound, nextStart, hasMore, err := h.store.History(id, filter, startSeq, highWater, limit)
240		if errors.Is(err, ErrDeviceNotFound) {
241			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
242			return
243		}
244		var gone *historyGoneError
245		if errors.As(err, &gone) {
246			writeJSON(w, http.StatusGone, map[string]any{
247				"error":            ErrHistoryGone.Error(),
248				"earliestSequence": gone.earliestSequence,
249			})
250			return
251		}
252		if err != nil {
253			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
254			return
255		}
256		highWater = appliedBound
257	
258		var nextCursor any
259		if hasMore {
260			nextCursor = encodeCursor(pageCursor{
261				DeviceID:  id,
262				From:      filter.From,
263				To:        filter.To,
264				HighWater: highWater,
265				StartSeq:  nextStart,
266				IID:       h.store.instanceID(),
267			})
268		}
269	
270		writeJSON(w, http.StatusOK, map[string]any{
271			"deviceId":   id,
272			"events":     events,
273			"nextCursor": nextCursor,
274		})
275	}
