408	func (h *handler) updateRule(w http.ResponseWriter, r *http.Request) {
409		var request struct {
410			Metric  *string  `json:"metric"`
411			Trigger *float64 `json:"trigger"`
412			Recover *float64 `json:"recover"`
413			Enabled *bool    `json:"enabled"`
414			Version int64    `json:"version"`
415		}
416		if err := decodeJSON(r, &request); err != nil {
417			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
418			return
419		}
420		if request.Version < 1 {
421			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version is required"})
422			return
423		}
424		if request.Metric != nil && strings.TrimSpace(*request.Metric) == "" {
425			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric must not be blank"})
426			return
427		}
428		if request.Trigger != nil && !finiteFloat(*request.Trigger) {
429			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "trigger must be a finite number"})
430			return
431		}
432		if request.Recover != nil && !finiteFloat(*request.Recover) {
433			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover must be a finite number"})
434			return
435		}
436		update := ruleUpdate{}
437		if request.Metric != nil {
438			metric := strings.TrimSpace(*request.Metric)
439			update.Metric = &metric
440		}
441		if request.Trigger != nil {
442			update.Trigger = request.Trigger
443		}
444		if request.Recover != nil {
445			update.Recover = request.Recover
446		}
447		if request.Enabled != nil {
448			update.Enabled = request.Enabled
449		}
450		rule, _, err := h.store.UpdateRule(r.PathValue("id"), r.PathValue("ruleId"), update, request.Version)
451		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrRuleNotFound) {
452			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
453			return
454		}
455		if errors.Is(err, ErrVersionConflict) {
456			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
457			return
458		}
459		if errors.Is(err, ErrInvalidRule) {
460			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
461			return
462		}
463		if errors.Is(err, ErrStorageUnavailable) {
464			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
465			return
466		}
467		if err != nil {
468			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
469			return
470		}
471		writeJSON(w, http.StatusOK, rule)
472	}
