476	func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
477		query := r.URL.Query()
478		filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
479		if raw := strings.TrimSpace(query.Get("status")); raw != "" {
480			if raw != alertStatusActive && raw != alertStatusEnded {
481				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
482				return
483			}
484			filter.Status = raw
485		}
486		if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
487			switch raw {
488			case "true", "1":
489				v := true
490				filter.Acknowledged = &v
491			case "false", "0":
492				v := false
493				filter.Acknowledged = &v
494			default:
495				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
496				return
497			}
498		}
499		alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
500		if errors.Is(err, ErrDeviceNotFound) {
501			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
502			return
503		}
504		if errors.Is(err, ErrRuleNotFound) {
505			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
506			return
507		}
508		if err != nil {
509			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
510			return
511		}
512		writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
513	}
