140	// knownSample is the durable replay-deduplication record for one eventId. It is
141	// retained even after the event itself leaves history through the retention
142	// limit, so a trimmed sample re-submitted later is still recognised as a
143	// duplicate (same content) or a conflict (different content).
144	type knownSample struct {
145		sequence   int64
146		observedAt time.Time
147		values     map[string]float64
148	}
