641	// ListRules returns a device's rules, ordered by rule id.
642	func (s *Store) ListRules(id string) ([]Rule, error) {
643		s.mu.RLock()
644		defer s.mu.RUnlock()
645		state, ok := s.devices[id]
646		if !ok {
647			return nil, ErrDeviceNotFound
648		}
649		rules := make([]Rule, 0, len(state.rules))
650		for _, rs := range state.rules {
651			rules = append(rules, cloneRule(rs.rule))
652		}
653		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
654		return rules, nil
655	}
656	
657	// AckAlert records the server time of the first acknowledgment. Repeated
658	// acknowledgments keep the original time and write nothing. It returns
659	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
660	// alert id.
661	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
662		s.mu.Lock()
663		defer s.mu.Unlock()
664		state, ok := s.devices[id]
665		if !ok {
666			return Alert{}, ErrDeviceNotFound
667		}
668		if alertID < 1 || int(alertID) > len(state.alerts) {
669			return Alert{}, ErrAlertNotFound
670		}
671		alert := state.alerts[alertID-1]
672		if alert.AcknowledgedAt != nil {
673			return cloneAlert(*alert), nil
674		}
675		now := s.now().UTC()
676		if s.wal != nil {
677			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
678				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
679			}); err != nil {
680				return Alert{}, storageUnavailable(err)
681			}
682		}
683		alert.AcknowledgedAt = &now
684		return cloneAlert(*alert), nil
685	}
686	
687	// ListAlerts returns a device's alerts with the given filters, ordered by
688	// alert id.
689	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
690		s.mu.RLock()
691		defer s.mu.RUnlock()
692		state, ok := s.devices[id]
693		if !ok {
694			return nil, ErrDeviceNotFound
695		}
696		if filter.RuleID != "" {
697			if _, ok := state.rules[filter.RuleID]; !ok {
698				return nil, ErrRuleNotFound
699			}
700		}
701		alerts := make([]Alert, 0, len(state.alerts))
702		for _, alert := range state.alerts {
703			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
704				continue
705			}
706			if filter.Status != "" && alert.Status != filter.Status {
707				continue
708			}
709			if filter.Acknowledged != nil {
710				acknowledged := alert.AcknowledgedAt != nil
711				if *filter.Acknowledged != acknowledged {
712					continue
713				}
714			}
715			alerts = append(alerts, cloneAlert(*alert))
716		}
717		return alerts, nil
718	}
719	
720	// alertEvaluator applies accepted samples to a device's enabled rules without
721	// mutating state until commit. It tracks which rule currently has an active
722	// alert so a trigger and a recovery inside the same batch are both handled in
723	// order.
724	type alertEvaluator struct {
725		state        *deviceState
726		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
727		created      []*Alert
728		ended        []*Alert
729		nextID       int64
730	}
731	
732	func newAlertEvaluator(state *deviceState) *alertEvaluator {
733		eval := &alertEvaluator{
734			state:        state,
735			activeByRule: make(map[string]int64, len(state.rules)),
736			nextID:       int64(len(state.alerts)) + 1,
737		}
738		for id, rs := range state.rules {
739			eval.activeByRule[id] = rs.activeAlertID
740		}
741		return eval
742	}
743	
744	// evaluate judges one accepted sample. A value at or above the trigger opens
745	// an alert (or keeps the existing one); a value at or below the recovery
746	// threshold ends the active alert; anything in between or a missing metric
747	// leaves state unchanged.
748	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
749		for _, rs := range eval.state.rules {
750			if !rs.rule.Enabled {
751				continue
752			}
753			value, ok := values[rs.rule.Metric]
754			if !ok {
755				continue
756			}
757			activeID := eval.activeByRule[rs.rule.ID]
758			if value >= rs.rule.Trigger && activeID == 0 {
759				alert := &Alert{
760					ID:                eval.nextID,
761					RuleID:            rs.rule.ID,
762					RuleVersion:       rs.rule.Version,
763					Metric:            rs.rule.Metric,
764					Trigger:           rs.rule.Trigger,
765					Recover:           rs.rule.Recover,
766					Status:            alertStatusActive,
767					TriggerSequence:   seq,
768					TriggerValue:      value,
769					TriggerObservedAt: observedAt,
770				}
771				eval.nextID++
772				eval.created = append(eval.created, alert)
773				eval.activeByRule[rs.rule.ID] = alert.ID
774			} else if value <= rs.rule.Recover && activeID != 0 {
775				var source *Alert
776				if activeID <= int64(len(eval.state.alerts)) {
777					source = eval.state.alerts[activeID-1]
778				} else {
779					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
780				}
781				alert := cloneAlert(*source)
782				alert.Status = alertStatusEnded
783				alert.EndReason = endReasonRecovered
784				alert.RecoverSequence = &seq
785				alert.RecoverValue = &value
786				alert.RecoverObservedAt = &observedAt
787				eval.ended = append(eval.ended, &alert)
788				eval.activeByRule[rs.rule.ID] = 0
789			}
790		}
791	}
792	
793	// commit publishes the planned alert changes to the device state.
794	func (eval *alertEvaluator) commit() {
795		applyAlertChanges(eval.state, eval.created, eval.ended)
796	}
797	
798	// applyAlertChanges appends created alerts and replaces ended ones, keeping
799	// each rule's active-alert pointer in sync. It is shared by live evaluation
800	// and WAL recovery.
801	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
802		for _, alert := range created {
803			state.alerts = append(state.alerts, alert)
804			if rs, ok := state.rules[alert.RuleID]; ok {
805				rs.activeAlertID = alert.ID
806			}
807		}
808		for _, alert := range ended {
809			state.alerts[alert.ID-1] = alert
810			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
811				rs.activeAlertID = 0
812			}
813		}
814	}
815	
816	func cloneRule(rule Rule) Rule {
817		return rule
818	}
819	
820	func cloneAlert(alert Alert) Alert {
821		if alert.RecoverSequence != nil {
822			seq := *alert.RecoverSequence
823			alert.RecoverSequence = &seq
824		}
825		if alert.RecoverValue != nil {
826			value := *alert.RecoverValue
827			alert.RecoverValue = &value
828		}
829		if alert.RecoverObservedAt != nil {
830			t := *alert.RecoverObservedAt
831			alert.RecoverObservedAt = &t
832		}
833		if alert.EndedAt != nil {
834			t := *alert.EndedAt
835			alert.EndedAt = &t
836		}
837		if alert.AcknowledgedAt != nil {
838			t := *alert.AcknowledgedAt
839			alert.AcknowledgedAt = &t
840		}
841		return alert
842	}
843	
844	func cloneAlerts(alerts []*Alert) []*Alert {
845		if alerts == nil {
846			return nil
847		}
848		cloned := make([]*Alert, len(alerts))
849		for i, alert := range alerts {
850			c := cloneAlert(*alert)
851			cloned[i] = &c
852		}
853		return cloned
854	}
855	
856	// historyGoneError carries the current earliest retained sequence alongside
857	// ErrHistoryGone so a 410 response can tell the client where the surviving
858	// history resumes.
859	type historyGoneError struct {
860		earliestSequence int64
861	}
862	
863	func (e *historyGoneError) Error() string { return ErrHistoryGone.Error() }
864	func (e *historyGoneError) Unwrap() error { return ErrHistoryGone }
865	
866	// History returns one page of a device's event history. startSeq is the first
867	// receive sequence to scan (1 or 0 for the first page, which begins at the
868	// current earliest retained event); limit caps the number of matching events
869	// returned. bound pins the scan to sequences no larger than bound; a zero
870	// bound means "current maximum", which is then returned so callers can pin
871	// subsequent pages. nextStart is the sequence a following page should start at
872	// when hasMore is true. Retention may have removed the start of a continuation
873	// page: then ErrHistoryGone is returned with the current earliest sequence, so
874	// the missing range is never skipped silently. Concurrent writes cannot skip
875	// or duplicate rows within a paged walk.
876	func (s *Store) History(id string, filter HistoryFilter, startSeq, bound int64, limit int) (events []Event, appliedBound, nextStart int64, hasMore bool, err error) {
877		s.mu.RLock()
878		defer s.mu.RUnlock()
879		state, ok := s.devices[id]
880		if !ok {
881			return nil, 0, 0, false, ErrDeviceNotFound
882		}
883		highWater := state.maxSequence()
884		if bound == 0 {
885			bound = highWater
886		}
887		continuation := startSeq > 0
888		if !continuation {
889			startSeq = state.earliestSequence()
890			if startSeq == 0 {
891				startSeq = 1
892			}
893		} else if startSeq < state.earliestSequence() || startSeq > state.maxSequence() {
894			// The exact record the continuation starts at (or a prefix containing
895			// it) was trimmed. Report 410 with the live window's first sequence
896			// instead of silently resuming partway through the pinned range.
897			return nil, bound, 0, false, &historyGoneError{earliestSequence: state.earliestSequence()}
898		}
899		events = make([]Event, 0, limit)
900		for seq := startSeq; seq <= bound; seq++ {
901			event := state.events[seq-1-state.eventBase]
902			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
903				continue
904			}
905			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
906				continue
907			}
908			if len(events) < limit {
909				events = append(events, cloneEvent(event))
910				continue
911			}
912			// This match belongs to the next page; resume scanning at its sequence
913			// so rows in the gap are never examined twice.
914			return events, bound, seq, true, nil
915		}
916		return events, bound, 0, false, nil
917	}
918	
919	func (s *Store) Snapshot() []Device {
920		s.mu.RLock()
921		defer s.mu.RUnlock()
922		result := make([]Device, 0, len(s.devices))
923		for _, state := range s.devices {
924			result = append(result, cloneDevice(state.device))
925		}
926		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
927		return result
928	}
929	
930	func cloneDevice(device Device) Device {
931		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
932		return device
933	}
934	
935	func cloneEvent(event Event) Event {
936		event.Values = cloneTelemetry(event.Values)
937		return event
938	}
939	
940	func cloneTelemetry(values map[string]float64) map[string]float64 {
941		if values == nil {
942			return nil
943		}
944		cloned := make(map[string]float64, len(values))
945		for key, value := range values {
946			cloned[key] = value
947		}
948		return cloned
949	}
950	
951	// sameInstant compares times as UTC instants.
952	func sameInstant(a, b time.Time) bool {
953		return a.UTC().Equal(b.UTC())
954	}
955	
956	// sameValues compares metric maps by key and value.
957	func sameValues(a, b map[string]float64) bool {
958		if len(a) != len(b) {
959			return false
960		}
961		for key, value := range a {
962			other, ok := b[key]
963			if !ok || value != other {
964				return false
965			}
966		}
967		return true
968	}
969	
970	// sameOrderedSamples reports whether two batches carry the same samples in the
971	// same order, compared as UTC instants and key/value maps.
972	func sameOrderedSamples(a, b []Sample) bool {
973		if len(a) != len(b) {
974			return false
975		}
976		for i := range a {
977			if a[i].EventID != b[i].EventID ||
978				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
979				!sameValues(a[i].Values, b[i].Values) {
980				return false
981			}
982		}
983		return true
984	}
